import re
from collections import defaultdict

def parse_ini(text: str) -> dict[str, dict[str, str]]:
    sections = defaultdict(dict)
    current_section = None
    current_key = None
    lines = text.splitlines()
    default_section = {}

    for line in lines:
        stripped_line = line.strip()
        if not stripped_line or stripped_line.startswith((';', '#')):
            continue

        # Check for section header
        section_match = re.match(r'^\s*\[([^\]]+)\]\s*$', line)
        if section_match:
            current_section = section_match.group(1).strip()
            if current_section.lower() == 'default':
                current_section = None
            else:
                sections[current_section] = {}
            continue

        # Check for key-value pair
        if '=' in line and ':' in line:
            sep = min(line.find('='), line.find(':'))
        elif '=' in line:
            sep = line.find('=')
        elif ':' in line:
            sep = line.find(':')
        else:
            raise ValueError(f"Malformed line: {line}")

        key_part = line[:sep].strip().lower()
        value_part = line[sep+1:].strip()

        # Check for inline comment
        inline_comment_match = re.search(r'(?<!\\)[\s]*(;|#).*$', value_part)
        if inline_comment_match:
            value_part = value_part[:inline_comment_match.start()].strip()

        # Check for quoted value
        if value_part.startswith('"') and value_part.endswith('"'):
            value_part = value_part[1:-1]
        else:
            value_part = value_part.strip()

        # Handle continuation lines
        if current_key is not None:
            if line.startswith((' ', '\t')):
                value_part = sections[current_section][current_key] + '\n' + value_part
                sections[current_section][current_key] = value_part
                continue
            else:
                current_key = None

        current_key = key_part
        sections[current_section][current_key] = value_part

    # Process DEFAULT section
    if None in sections:
        default_section = sections.pop(None)

    # Apply interpolation
    for section_name, section in sections.items():
        section.update(default_section)
        for key in list(section.keys()):
            section[key] = interpolate_value(section, key, sections)

    return sections

def interpolate_value(section: dict[str, str], key: str, all_sections: dict[str, dict[str, str]]) -> str:
    value = section[key]
    pattern = re.compile(r'\$\{(?:([^:]+):)?([^}]+)\}')
    while True:
        match = pattern.search(value)
        if not match:
            break
        section_name, inner_key = match.groups()
        if section_name is None:
            if inner_key not in section:
                raise KeyError(f"Missing key: {inner_key}")
            replacement = section[inner_key]
        else:
            if section_name not in all_sections:
                raise KeyError(f"Missing section: {section_name}")
            if inner_key not in all_sections[section_name]:
                raise KeyError(f"Missing key: {inner_key} in section {section_name}")
            replacement = all_sections[section_name][inner_key]
        value = value[:match.start()] + replacement + value[match.end():]

    return value
