from collections import OrderedDict

class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock):
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self.cache = OrderedDict()
        self.stats = {
            "hits": 0,
            "misses": 0,
            "evictions": 0,
            "expirations": 0
        }

    def _clean_expired(self):
        now = self.clock()
        expired_keys = []
        for key, (value, expiry) in list(self.cache.items()):
            if now >= expiry:
                expired_keys.append(key)
        for key in expired_keys:
            del self.cache[key]
            self.stats["expirations"] += 1

    def put(self, key, value):
        if self.capacity == 0:
            return

        now = self.clock()
        expiry = now + self.ttl

        if key in self.cache:
            # Update existing entry
            del self.cache[key]
            self.cache[key] = (value, expiry)
            self.cache.move_to_end(key)
        else:
            # Insert new entry
            if len(self.cache) >= self.capacity:
                self._clean_expired()
                if len(self.cache) >= self.capacity:
                    evicted_key, _ = self.cache.popitem(last=False)
                    self.stats["evictions"] += 1
            self.cache[key] = (value, expiry)
            self.cache.move_to_end(key)

    def get(self, key, default=None):
        if self.capacity == 0:
            self.stats["misses"] += 1
            return default

        now = self.clock()
        if key in self.cache:
            value, expiry = self.cache[key]
            if now >= expiry:
                del self.cache[key]
                self.stats["expirations"] += 1
                self.stats["misses"] += 1
                return default
            else:
                self.cache.move_to_end(key)
                self.stats["hits"] += 1
                return value
        else:
            self.stats["misses"] += 1
            return default

    def __len__(self):
        now = self.clock()
        return sum(1 for _, (_, expiry) in self.cache.items() if now < expiry)

    def stats(self):
        return self.stats.copy()
