def parse_duration(s: str) -> int:
    if not s or s.isspace():
        raise ValueError("Empty or blank string")

    parts = []
    for part in s.split():
        if not part:
            continue
        if 'h' in part:
            if part.lower() != 'h':
                raise ValueError("Invalid format for hours")
            parts.append(('h', 1))
        elif 'm' in part:
            if part.lower() != 'm':
                raise ValueError("Invalid format for minutes")
            parts.append(('m', 2))
        elif 's' in part:
            if part.lower() != 's':
                raise ValueError("Invalid format for seconds")
            parts.append(('s', 3))
        else:
            raise ValueError("Unknown unit")

    if not parts:
        raise ValueError("No valid parts found")

    # Check for repeated units
    units = [unit for unit, _ in parts]
    if len(units) != len(set(units)):
        raise ValueError("Repeated units")

    # Check order of units
    expected_order = ['h', 'm', 's']
    for i, (unit, _) in enumerate(parts):
        if i < len(expected_order) and unit != expected_order[i]:
            raise ValueError("Units out of order")

    # Parse numbers
    total_seconds = 0
    for i, (unit, multiplier) in enumerate(parts):
        try:
            num = int(part.split(unit)[0])
        except ValueError:
            raise ValueError("Invalid number format")
        if num < 0:
            raise ValueError("Negative number")
        if unit == 'h':
            total_seconds += num * 3600
        elif unit == 'm':
            total_seconds += num * 60
        elif unit == 's':
            total_seconds += num
    return total_seconds
