def summarize_ranges(nums: list[int]) -> str:
    if not nums:
        return ""

    unique_sorted = sorted(set(nums))
    result = []
    start = unique_sorted[0]

    for i in range(1, len(unique_sorted)):
        if unique_sorted[i] != unique_sorted[i - 1] + 1:
            if unique_sorted[i - 1] - start >= 2:
                result.append(f"{start}..{unique_sorted[i - 1]}")
            else:
                for num in range(start, unique_sorted[i - 1] + 1):
                    result.append(str(num))
            start = unique_sorted[i]

    # Handle the last range
    if unique_sorted[-1] - start >= 2:
        result.append(f"{start}..{unique_sorted[-1]}")
    else:
        for num in range(start, unique_sorted[-1] + 1):
            result.append(str(num))

    return ",".join(result)
