import time
from typing import Callable

class TokenBucket:
    def __init__(self, capacity: float, refill_per_sec: float, clock: Callable[[], float]):
        if capacity <= 0 or refill_per_sec < 0:
            raise ValueError("Capacity must be positive and refill rate must be non-negative")
        self._capacity = capacity
        self._refill_rate = refill_per_sec
        self._clock = clock
        self._last_refill_time = clock()
        self._tokens = capacity

    def _refill(self) -> None:
        now = self._clock()
        elapsed = now - self._last_refill_time
        if elapsed > 0:
            refill_amount = elapsed * self._refill_rate
            self._tokens = min(self._tokens + refill_amount, self._capacity)
            self._last_refill_time = now

    def allow(self, cost: float = 1) -> bool:
        self._refill()
        if self._tokens >= cost:
            self._tokens -= cost
            return True
        return False

    @property
    def tokens(self) -> float:
        self._refill()
        return self._tokens
